commands.command:
set -eu
git fetch origin work/ux-evolution
test "$(git rev-parse HEAD)" = "$(git rev-parse origin/work/ux-evolution)"
test -z "$(git status --porcelain)"
python3 - <<'PY'
from pathlib import Path
p=Path('apps/mobile/src/screens/hardware-setup/pages/ShellySetupPresentation.tsx')
s=p.read_text()
a="import { IonInput } from '@ionic/react';"
assert s.count(a)==1
s=s.replace(a,"import { IonButton, IonInput } from '@ionic/react';")
old='''        <button
          className="shelly-ble-action"
          type="button"
          disabled={isControlBusy}
          title={t('hardware.shelly.scanBleViaShellyTitle')}
          onClick={() => onBleScan(device)}
        >
          <IconBluetooth className="icon-action__svg" aria-hidden="true" />
          <span>{t('hardware.shelly.scanBleViaShellyTitle')}</span>
        </button>'''
new='''        <IonButton
          className="shelly-ble-action"
          fill="clear"
          size="small"
          type="button"
          disabled={isControlBusy}
          aria-label={t('hardware.shelly.scanBleViaShellyTitle')}
          title={t('hardware.shelly.scanBleViaShellyTitle')}
          onClick={() => onBleScan(device)}
        >
          <IconBluetooth className="icon-action__svg" aria-hidden="true" />
          <span>{t('hardware.shelly.scanBleViaShellyTitle')}</span>
        </IonButton>'''
assert s.count(old)==1
p.write_text(s.replace(old,new))
p=Path('apps/mobile/src/theme/theme.css')
s=p.read_text()
old='''.shelly-ble-action {
  align-items: center;
  align-self: start;
  background: transparent;
  border: 0;
  color: var(--lcl-color-accent);
  cursor: pointer;
  display: inline-flex;
  font-size: var(--lcl-font-size-sm);
  font-weight: var(--lcl-font-weight-bold);
  gap: var(--lcl-spacing-xs);
  justify-content: flex-start;
  min-height: var(--lcl-size-compact-control-min-height);
  padding: 0;
  text-align: left;
  width: fit-content;
}

.shelly-ble-action:disabled {
  cursor: not-allowed;
  opacity: var(--lcl-opacity-disabled);
}'''
new='''.shelly-ble-action {
  --background: transparent;
  --background-hover: transparent;
  --background-activated: transparent;
  --box-shadow: none;
  --color: var(--lcl-color-accent);
  --padding-bottom: 0;
  --padding-end: 0;
  --padding-start: 0;
  --padding-top: 0;

  align-self: start;
  font-size: var(--lcl-font-size-sm);
  font-weight: var(--lcl-font-weight-bold);
  margin: 0;
  min-height: var(--lcl-size-compact-control-min-height);
  text-transform: none;
  width: fit-content;
}

.shelly-ble-action::part(native) {
  gap: var(--lcl-spacing-xs);
  justify-content: flex-start;
  text-align: left;
}

.shelly-ble-action[disabled] {
  opacity: var(--lcl-opacity-disabled);
}'''
assert s.count(old)==1
p.write_text(s.replace(old,new))
p=Path('apps/mobile/src/__tests__/hardware-setup.test.tsx')
s=p.read_text()
a="""const openShellyBleScanFromSettings = async () => {
  fireEvent.click(
    screen.getByRole('button', { name: 'Skanuj termometry BLE przez to gniazdko' })
  );
};"""
b="""const openShellyBleScanFromSettings = async () => {
  fireEvent.click(getIonicButton(document, 'Skanuj termometry BLE przez to gniazdko'));
};"""
assert s.count(a)==1
assert 'getIonicButton' in s
s=s.replace(a,b)
old_assertion="""    expect(
      within(savedPlugList).getByRole('button', {
        name: 'Skanuj termometry BLE przez to gniazdko'
      })
    ).toBeInTheDocument();"""
new_assertion="""    expect(
      getIonicButton(savedPlugList, 'Skanuj termometry BLE przez to gniazdko')
    ).toBeInTheDocument();"""
assert s.count(old_assertion)==3, 'saved Plug tests changed unexpectedly'
p.write_text(s.replace(old_assertion,new_assertion))
PY
pnpm exec prettier --write apps/mobile/src/screens/hardware-setup/pages/ShellySetupPresentation.tsx apps/mobile/src/theme/theme.css apps/mobile/src/__tests__/hardware-setup.test.tsx
pnpm --filter @lcl/mobile exec vitest run src/__tests__/hardware-setup.test.tsx --reporter=dot >/tmp/shelly-ionic-card-ble-179-focused.log 2>&1 || {
 echo 'FOCUSED_TEST_FAILED'
 grep -E 'FAIL|Error|Test Files|Tests ' /tmp/shelly-ionic-card-ble-179-focused.log | tail -40 || true
 tail -38 /tmp/shelly-ionic-card-ble-179-focused.log
 exit 33
}
grep -E 'Test Files|Tests ' /tmp/shelly-ionic-card-ble-179-focused.log | tail -5
pnpm --filter @lcl/mobile typecheck
git diff --check
git add apps/mobile/src/screens/hardware-setup/pages/ShellySetupPresentation.tsx apps/mobile/src/theme/theme.css apps/mobile/src/__tests__/hardware-setup.test.tsx
git commit -m "refactor(ionic): use compact Ionic action for saved Shelly BLE scan"
git push origin HEAD:refs/heads/work/ux-evolution
echo "MIGRATION_COMMIT=$(git rev-parse HEAD)"
git status --short
